const invalidJsonString = "{ 'orderId': 'ORD-101', }"; // Dùng dấu nháy đơn và thừa dấu phẩy cuối

// SAI: Gọi JSON.parse trực tiếp mà không bắt lỗi
const orderData = JSON.parse(invalidJsonString); // Quăng lỗi Uncaught SyntaxError làm ngắt chương trình

gotchas_and_errors.code_good:
const invalidJsonString = "{ 'orderId': 'ORD-101', }";

// ĐÚNG: Luôn bọc JSON.parse trong khối try...catch để xử lý an toàn
try {
  const orderData = JSON.parse(invalidJsonString);
  console.log(orderData);
} catch (error) {
  console.error("[WARNING] Không thể giải mã JSON do sai định dạng:", error.message);
  // Thực hiện phương án dự phòng (fallback)
}
